export const buildQuizzes = (chapters: Chapter[]): Quiz[] =>
  chapters.map((chapter) => {
    const configuredQuiz = quizzes.find((quiz) => quiz.chapterId === chapter.id);

    if (!configuredQuiz) {
      return {
        chapterId: chapter.id,
        questions: [],
      };
    }

    return {
      ...configuredQuiz,
      questions: configuredQuiz.questions ?? [],
    };
  });

